using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "MercifulConvergenceCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Orion/MercifulConvergenceCustomDescription", order = 0)]
public class MercifulConvergenceCustomDescription : EffectStarRequirementCustomDescription
{
	protected override string GetActionLocalizedDescription(string amountModified, BattleAction battleAction)
	{
		MercifulConvergenceAction mercifulConvergenceAction = battleAction as MercifulConvergenceAction;
		string firstArgument = Smart.Format(base.localizationManager.GetLocalizedCastOrbActionBase(), mercifulConvergenceAction.StarAbility.StarAbilityID.GetSpriteText() + mercifulConvergenceAction.StarAbility.GetLocalizedNameWithoutModifiers());
		firstArgument = base.localizationManager.GetLocalizedXTimesFormatted(firstArgument, mercifulConvergenceAction.KarmicOrbActivationAmount);
		return base.GetActionLocalizedDescription(amountModified, battleAction) + "\n" + firstArgument;
	}
}
